/** Shown when a tool has no mapping yet, so a new slug degrades gracefully. */
const FALLBACK_ICON: IconDef = {
  name: "file",
  viewBox: "0 0 384 512",
  d: "M64 0C28.7 0 0 28.7 0 64L0 448c0 35.3 28.7 64 64 64l256 0c35.3 0 64-28.7 64-64l0-277.5c0-17-6.7-33.3-18.7-45.3L258.7 18.7C246.7 6.7 230.5 0 213.5 0L64 0zM325.5 176L232 176c-13.3 0-24-10.7-24-24L208 58.5 325.5 176z",
};

export function toolIconId(category: string, slug: string): string {
  return `${category}/${slug}`;
}

export function ToolIcon({
  category,
  slug,
  size = 22,
  className,
}: {
  category: string;
  slug: string;
  size?: number;
  className?: string;
}) {
  const icon = ICONS[toolIconId(category, slug)] ?? FALLBACK_ICON;

  return (
    <svg
      width={size}
      height={size}
      viewBox={icon.viewBox}
      fill="currentColor"
      className={className}
      aria-hidden="true"
      focusable="false"
    >
      <path d={icon.d} />
    </svg>
  );
}
